// Arena-fuzz native L1 for a ported batch (tests/arena_fuzz.h). Generated by tools/asm_port/gen_fuzz_test.py.
// Light_SetFalloffRange (0x00453400) is skipped: it sprintf()s with the format string at 0x004ded84, which the arena
// randomises (KG-31: formatted output from random state); tests/test_zclass_accessors_native.cpp covers it with real floats.
#include "test.h"
#include "arena_fuzz.h"
#include "platform/image/original_data.h"
#include "GameZRecoil/zClass/Light.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace {
struct Entry { std::uint32_t va; void* port; int nstack; const char* name; std::vector<std::uint32_t> globals, kept; };
std::vector<Entry> entries()
{
    return {
        {0x00453200, reinterpret_cast<void*>(&recoil::Light_SetFieldA8), 1, "Light_SetFieldA8", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x00453250, reinterpret_cast<void*>(&recoil::Light_SetFieldA4), 1, "Light_SetFieldA4", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x004532a0, reinterpret_cast<void*>(&recoil::Light_SetFieldB8), 0, "Light_SetFieldB8", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x004532f0, reinterpret_cast<void*>(&recoil::Light_SetModeBC), 0, "Light_SetModeBC", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x00453350, reinterpret_cast<void*>(&recoil::Light_SetModeC0), 0, "Light_SetModeC0", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x004533b0, reinterpret_cast<void*>(&recoil::Light_SetFieldC4), 0, "Light_SetFieldC4", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x00453500, reinterpret_cast<void*>(&recoil::Light_GetFalloffRange), 1, "Light_GetFalloffRange", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x00453560, reinterpret_cast<void*>(&recoil::Light_SetVec14), 3, "Light_SetVec14", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x004535c0, reinterpret_cast<void*>(&recoil::Light_SetVec08), 3, "Light_SetVec08", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
        {0x00453a40, reinterpret_cast<void*>(&recoil::Light_GetColor), 2, "Light_GetColor", {0x004dd9bc, 0x004dd9d4, 0x004ded18}, {}},
    };
}
}  // namespace

TEST(native_fuzz_zclass2_match_original)
{
    if (!rt::map_original()) { CHECK(false); return; }
    int failed = 0;
    const char* only = std::getenv("RECOIL_ONLY");  // diagnostics: run one function by name
    int shard = 0, shards = 1;  // RECOIL_SHARD=i/n: this process runs entries i, i+n, ... (tools/run_tests.py)
    if (const char* s = std::getenv("RECOIL_SHARD")) std::sscanf(s, "%d/%d", &shard, &shards);
    int index = 0;
    for (const Entry& e : entries()) {
        if (index++ % shards != shard) continue;
        if (only && std::strcmp(only, e.name) != 0) continue;
        std::printf("  run  %s\n", e.name); std::fflush(stdout);  // names the function if a crash escapes
        std::vector<af::GlobalRange> gr;
        for (std::uint32_t g : e.globals) gr.push_back({g, recoil::ImageData_Address(g), 4});
        for (std::uint32_t g : e.kept) gr.push_back({g, recoil::ImageData_Address(g), 4, true});  // callee-only: pristine each call
        const af::Result r = af::run(e.va, e.port, e.nstack, 1000, e.va, gr);
        std::printf("  %-40s calls %5d abnormal %5d %s%s\n", e.name, r.calls, r.abnormal, r.bad ? "DIFF " : "ok", r.first.c_str());
        if (r.bad || r.calls - r.abnormal < 50) ++failed;  // at least 50 calls that ended normally (and compared data)
    }
    CHECK_EQ(failed, 0);
}
